-- pcsx-redux GTE dumper for Spyro 1 LOADING-TEXT scene (f1305..f1315)
--
-- Wider scope than the titlescreen variant: instruments ALL 334
-- gte_execute call sites in PSX.EXE_full.c (vs the 79-PC subset),
-- so the loading-text renderer's RTPS / NCDS / etc. all get logged.
-- Generated by extract-cop2-pcs from PSX.EXE_full.c on 2026-04-25.
--
-- Counts VSync events as frames, presses Start at scheduled frames to reach
-- the cutscene, then on each cop2 imm-25 instruction in r_pete + r_environment
-- (range 0x80023AC4..0x8002B9CC) emits one CSV row matching the openpete
-- trace logger's "psy" engine layout. After CFG.frame_hi we quit.

local CFG = {
    csv_path  = '/tmp/pcsx-redux-gte-loading-text.csv',
    -- pcsx-redux frame numbers (no fast-boot, so later than openpete).
    -- Will tune empirically; for first run, dump everything in a wide window.
    frame_lo  = 1300,
    frame_hi  = 1320,
    -- Press timings matching openpete's
    -- --press 861:return,931:return,1037:return,1073:return,1919:return
    -- (return = Start = button 3 in PsyCross/pcsx-redux libpad mapping).
    -- pcsx-redux frames may differ from openpete's because openpete uses
    -- --fast-boot-until-frame=850 (skips host yields, but PSX CPU still
    -- runs); pcsx-redux runs the full BIOS+boot. The frame numbers
    -- below should match openpete since both count VSyncs from boot.
    -- If the loading-text never appears in the capture, sweep these
    -- forward by 100..400 frames empirically.
    presses   = {
        [861]  = 3,
        [931]  = 3,
        [1037] = 3,
        [1073] = 3,
        [1919] = 3,
    },
    press_dur = 6,
}

